#include <iostream>
#include <string>
using namespace std;

char st[1005];

int main() {
    int n;
    if (!(cin >> n)) return 0;
    string line;
    getline(cin, line);

    while (n--) {
        getline(cin, line);
        int top = -1;
        bool ok = true;
        for (char c : line) {
            if (c == '(' || c == '<' || c == '^') {
                st[++top] = c;
            } else if (c == ')' || c == '>' || c == 'v') {
                if (top < 0) { ok = false; break; }
                char t = st[top];
                bool match = (c == ')' && t == '(') || (c == '>' && t == '<') || (c == 'v' && t == '^');
                if (!match) { ok = false; break; }
                top--;
            }
        }
        if (top >= 0) ok = false;
        cout << (ok ? "Yes\n" : "No\n");
    }
    return 0;
}
